using KB.Core.Infrastructure;using KB.Core.Interfaces;using KB.Domain.Entities;namespace KB.Core.Features.Authentication.RefreshToken;public sealed class RefreshTokenCommandHandler(    IAuthenticationService authenticationService,    ITokenService tokenService){    private readonly IAuthenticationService _authenticationService = authenticationService;    private readonly ITokenService _tokenService = tokenService;    public async Task<Result<RefreshTokenResponse>> Handle(RefreshTokenCommand request, CancellationToken cancellationToken)    {        ArgumentNullException.ThrowIfNull(request);        var validationResult = ValidationHelper.Validate(request);        if (!validationResult.IsSuccess)        {            return Result<RefreshTokenResponse>.Invalid([.. validationResult.Errors]);        }        var userWithToken = await _authenticationService.GetUserWithRefreshTokenByTokenAsync(request.RefreshToken, cancellationToken);        if (userWithToken == null)        {            return Result<RefreshTokenResponse>.NotFound("Invalid refresh token.");        }        var refreshToken = userWithToken.RefreshTokens.First(rt => rt.Token == request.RefreshToken);        if (!refreshToken.IsValid())        {            return Result<RefreshTokenResponse>.Invalid("Refresh token is expired or revoked.");        }        var roles = await _authenticationService.GetUserRolesAsync(userWithToken.Id, cancellationToken);        var role = roles.FirstOrDefault() ?? userWithToken.Role.ToString();        var newAccessToken = _tokenService.GenerateAccessToken(userWithToken.Id, userWithToken.Email!, role);        var newRefreshTokenString = _tokenService.GenerateRefreshToken();        refreshToken.Revoke();        var newRefreshToken = Domain.Entities.RefreshToken.Create(            newRefreshTokenString,            userWithToken.Id,            DateTimeOffset.UtcNow.AddDays(30));        userWithToken.RefreshTokens.Add(newRefreshToken);        await _authenticationService.UpdateUserAsync(userWithToken, cancellationToken);        return Result<RefreshTokenResponse>.Success(new RefreshTokenResponse(            AccessToken: newAccessToken,            RefreshToken: newRefreshTokenString));    }}